using System;
namespace XiiiXR;
// The mod's own recordings, mono PCM16 at 48 kHz. Decoded only during FMOD cache creation.
// 0.1.121: ("m16",0) = the mod's M4 magazine-out recording (m4 mag out.m4a, peak-matched to the others, 2 ms fades).
internal static class SelectedReloadSounds {
 internal static float[]? Get(string profile,int kind) {
 string? encoded=(profile,kind) switch {
("pistol",0)=>"",
("pistol",1)=>"",
("pistol",3)=>"",
("ak47",0)=>"",
("ak47",1)=>"",
("ak47",3)=>"",
("shotgun",5)=>"",
("shotgun",4)=>"",
("shotgun",3)=>"",
("shotgun",2)=>"",
("shotgun",6)=>"",
("shotgun",7)=>"",
("shotgun",8)=>"",
("shotgun",9)=>"",
("shotgun",10)=>"",
("revolver",0)=>"",
("revolver",2)=>"",
("revolver",4)=>"",
("revolver",7)=>"",
("revolver",8)=>"",
("revolver",1)=>"",
("sniper",0)=>"",
("sniper",9)=>"",
("sniper",3)=>"",
("m16",0)=>"",
 _=>null};
 if(encoded==null)return null;
 var bytes=Convert.FromBase64String(encoded);var pcm=new float[bytes.Length/2];
 for(int i=0;i<pcm.Length;i++)pcm[i]=(short)(bytes[i*2]|bytes[i*2+1]<<8)/32768f;
 return pcm;
 }
}
